import java.util.*;
import java.io.*;

class HungarianSolver {
    public static final int MAXN = 2000;
    int matchCount, matchPos[], matchRev[];
    public HungarianSolver() {
        matchPos = new int[MAXN];
        matchRev = new int[MAXN];
    }
    public int solve(int n, List<Integer>[] adj) {
        matchCount = 0;
        Arrays.fill(matchPos, -1);
        Arrays.fill(matchRev, -1);
        boolean[] used = new boolean[MAXN];
        for (int i = 0; i < n; i++) {
            Arrays.fill(used, false);
            if (tryMatch(i, adj, used)) matchCount++;
        }
        return matchCount;
    }
    private boolean tryMatch(int u, List<Integer>[] adj, boolean[] used) {
        for (int v : adj[u]) {
            if (!used[v]) {
                used[v] = true;
                if (matchRev[v] < 0 || tryMatch(matchRev[v], adj, used)) {
                    matchPos[u] = v;
                    matchRev[v] = u;
                    return true;
                }
            }
        }
        return false;
    }
}

public class Main {
    static final int INF = 1000000000;
    static final int[] dr = {0, -1, 0, 1};
    static final int[] dc = {1, 0, -1, 0};
    static int[][] a = new int[12][12], b = new int[12][12], f = new int[12][12];
    static int n, t;
    static List<Integer>[] e = new ArrayList[2000];
    static List<Integer>[][] c = new ArrayList[12][12];

    static {
        for (int i = 0; i < 2000; i++) e[i] = new ArrayList<>();
        for (int i = 0; i < 12; i++) {
            for (int j = 0; j < 12; j++) {
                c[i][j] = new ArrayList<>();
            }
        }
    }

    static void floodfill(int sr, int sc) {
        Queue<Integer> qr = new LinkedList<>();
        Queue<Integer> qc = new LinkedList<>();
        for (int[] row : f) Arrays.fill(row, -1);
        qr.offer(sr);
        qc.offer(sc);
        f[sr][sc] = 0;
        while (!qr.isEmpty()) {
            int r = qr.poll();
            int c_ = qc.poll();
            for (int i = 0; i < 4; i++) {
                int tr = r + dr[i], tc = c_ + dc[i];
                if (tr >= 0 && tr < n && tc >= 0 && tc < n && a[tr][tc] >= 0 && f[tr][tc] < 0) {
                    f[tr][tc] = f[r][c_] + 1;
                    qr.offer(tr);
                    qc.offer(tc);
                }
            }
        }
    }

    static void setmark(int sr, int sc, int cnt) {
        int[][] v = new int[12][12];
        for (int[] row : v) Arrays.fill(row, -1);
        Queue<Integer> qr = new LinkedList<>();
        Queue<Integer> qc = new LinkedList<>();
        qr.offer(sr);
        qc.offer(sc);
        v[sr][sc] = 0;
        while (!qr.isEmpty()) {
            int r = qr.poll();
            int c_ = qc.poll();
            if (v[r][c_] > Math.min(t, f[r][c_])) continue;
            for (int j : c[r][c_]) {
                for (int i = 0; i < cnt; i++) {
                    e[n + i].add(j);
                }
            }
            if (v[r][c_] == Math.min(t, f[r][c_])) continue;
            for (int i = 0; i < 4; i++) {
                int tr = r + dr[i], tc = c_ + dc[i];
                if (tr >= 0 && tr < n && tc >= 0 && tc < n && a[tr][tc] >= 0 && v[tr][tc] < 0) {
                    v[tr][tc] = v[r][c_] + 1;
                    qr.offer(tr);
                    qc.offer(tc);
                }
            }
        }
        n += cnt;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        int m = 0, o = 0, sr = -1, sc = -1;
        st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());
        for (int[] row : a) Arrays.fill(row, -1);
        for (int[] row : b) Arrays.fill(row, -1);
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            for (int j = 0; j < n; j++) {
                char ch = line.charAt(j);
                if (ch >= '0' && ch <= '9') a[i][j] = ch - '0';
                if (ch == 'Z') {
                    sr = i;
                    sc = j;
                }
            }
        }
        floodfill(sr, sc);
        br.readLine(); // consume the empty line
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            for (int j = 0; j < n; j++) {
                char ch = line.charAt(j);
                if (ch >= '0' && ch <= '9') b[i][j] = ch - '0';
                for (int k = 0; k < b[i][j]; k++) {
                    c[i][j].add(o++);
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (f[i][j] < 0) f[i][j] = INF;
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (a[i][j] > 0) setmark(i, j, a[i][j]);
            }
        }
        HungarianSolver match = new HungarianSolver();
        System.out.println(match.solve(m, e));
    }
}

